package br.com.fiap.bank.core.infrastructure;
import org.springframework.stereotype.Repository;import br.com.fiap.bank.core.domain.*;import java.util.*;@Repository public class ClienteAdapter implements ClienteRepository {private final ClienteSpringRepository db;public ClienteAdapter(ClienteSpringRepository db){this.db=db;}private Cliente toDomain(ClienteJpa x){return new Cliente(x.id,x.cpf,x.nome,x.email,x.dataNascimento,x.rendaMensal);}public Cliente save(Cliente c){ClienteJpa x=new ClienteJpa();x.id=c.id();x.cpf=c.cpf();x.nome=c.nome();x.email=c.email();x.dataNascimento=c.dataNascimento();x.rendaMensal=c.rendaMensal();return toDomain(db.save(x));}public Optional<Cliente> byId(Long id){return db.findById(id).map(this::toDomain);}public Optional<Cliente> byCpf(String cpf){return db.findByCpf(cpf).map(this::toDomain);}public List<Cliente> all(){return db.findAll().stream().map(this::toDomain).toList();}public void delete(Long id){db.deleteById(id);}}